(* [comment removed for export] *)
Lemma SUPP_geom : forall i E1 A1 M1 m1 a, (2 <= i < PSO.NCUT)%nat -> AAMB I i E1 A1 M1 m1 ->
  SUPP I (bptrI i E1) (bcapI i E1) (sbI i E1) (scapI i E1) a ->
  let F := CL5A.uv E1 FE in
