Lemma XGEOM : forall i E1 A1 M1 m1 a, (2 <= i < PSO.NCUT)%nat -> AAMB I i E1 A1 M1 m1 -> PSOIW.xfoot I gx a ->
  let F := CL5A.uv E1 FE in
  0 <= a < 2 ^ 64 /\ a < sp - SCR /\ ~ (F <= a < F + 1024) /\ ~ in_shadow_of F 1024 a /\ ~ (P <= a < P + 272) /\ (PSOX.FLF I E1 -> a <> CL5A.uv E1 FLE) /\ a <> bptrI i E1 /\
